package se.helmer.rikslunchensaldo.model;

import com.j256.ormlite.field.DatabaseField;

import java.math.BigDecimal;
import java.util.Date;

public class Card {

    // id is generated by the database and set on the object automagically
    @DatabaseField(generatedId = true)
    private int _id;
    @DatabaseField(columnName = Contract.Card.CARD_ID)
    private String cardId;
    @DatabaseField(columnName = Contract.Card.LAST_TOPUP_DATE)
    private String lastTopupDate;  // Dates should be stored in UTC

    public Card() {

    }

    public void setData(String cardId, String lastTopupDate) {
        this.cardId = cardId;
        this.lastTopupDate = lastTopupDate;
    }

    public String getCardId() {
        return cardId;
    }

    public String getLastTopupDate() {
        return lastTopupDate;
    }

    public Card(String cardId, String lastTopupDate) {
        this.cardId = cardId;
        this.lastTopupDate = lastTopupDate;
    }
}
